local CheeseMaker = {}
local PRODUCTS = {
    fresh_curd = { name = "Sveža skuta", milkCost = 2, rennetCost = 1, time = 1, cost = 15, flavorStrength = 20, happiness = 1, description = "Sveža skuta za vsakdanjo rabo." },
    soft_cheese = { name = "Mehki sir", milkCost = 3, rennetCost = 1, saltCost = 1, time = 3, cost = 40, flavorStrength = 35, happiness = 2, prestige = 1, description = "Mehki sir z nežnim okusom." },
    hard_cheese = { name = "Trdi sir", milkCost = 4, rennetCost = 1, saltCost = 1, time = 6, cost = 100, flavorStrength = 55, happiness = 3, prestige = 3, description = "Trdi sir za dolgo shranjevanje." },
    aged_cheese = { name = "Staran sir", milkCost = 5, rennetCost = 1, saltCost = 1, spiceCost = 1, time = 9, cost = 240, flavorStrength = 75, happiness = 5, prestige = 7, description = "Staran sir z bogatim okusom." },
    spiced_cheese = { name = "Začinjen sir", milkCost = 5, rennetCost = 1, saltCost = 1, spiceCost = 2, silverCost = 1, time = 12, cost = 560, flavorStrength = 90, happiness = 7, prestige = 13, description = "Začinjen sir s srebrno korekcijo za plemiče." },
    royal_grand_cheese = { name = "Kraljevski veliki sir", milkCost = 10, goldCost = 1, silverCost = 1, jewelCost = 1, rennetCost = 2, saltCost = 2, spiceCost = 3, time = 18, cost = 1800, flavorStrength = 100, happiness = 15, prestige = 38, description = "Veliki kraljevski sir z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Sirarska delavnica", cost = { gold = 300, wood = 130, stone = 200 }, upkeep = 7, qualityBonus = 5 },
    dairy = { name = "Sirarna", cost = { gold = 950, wood = 250, stone = 400, milk = 10 }, upkeep = 23, qualityBonus = 18 },
    aging_cave = { name = "Starilna klet", cost = { gold = 2400, wood = 350, stone = 700, silver = 30, salt = 10 }, upkeep = 58, qualityBonus = 30 },
    royal_cheese_atelier = { name = "Kraljevski atelje sirov", cost = { gold = 9500, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 40 },
}
CheeseMaker.milkStock = 22; CheeseMaker.rennetStock = 14; CheeseMaker.saltStock = 14; CheeseMaker.spiceStock = 10; CheeseMaker.silverStock = 8; CheeseMaker.goldStock = 6; CheeseMaker.jewelStock = 6
CheeseMaker.productStock = {}; CheeseMaker.buildings = {}; CheeseMaker.maker = nil; CheeseMaker.activeMaking = {}; CheeseMaker.totalProducts = 0; CheeseMaker.dayTimer = 0
function CheeseMaker.init() CheeseMaker.milkStock=22; CheeseMaker.rennetStock=14; CheeseMaker.saltStock=14; CheeseMaker.spiceStock=10; CheeseMaker.silverStock=8; CheeseMaker.goldStock=6; CheeseMaker.jewelStock=6; CheeseMaker.productStock={}; CheeseMaker.buildings={}; CheeseMaker.maker=nil; CheeseMaker.activeMaking={}; CheeseMaker.totalProducts=0; CheeseMaker.dayTimer=0; print("[CheeseMaker] Royal Cheese Maker System initialized (6 products, 4 buildings)") end
function CheeseMaker.hireMaker(n,s) s=s or math.random(50,90); local c=520+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CheeseMaker.maker={name=n or ("Sirar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sirar najet: %s (spretnost: %d)",CheeseMaker.maker.name,s),"success") end; return true end
function CheeseMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CheeseMaker.build(id) local ok,e=CheeseMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CheeseMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CheeseMaker.getQualityBonus() local b=0; for _,bd in ipairs(CheeseMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CheeseMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.milkCost and CheeseMaker.milkStock<(d.milkCost or 0) then return false,"Premalo mleka" end; if d.rennetCost and CheeseMaker.rennetStock<(d.rennetCost or 0) then return false,"Premalo sirila" end; if d.saltCost and CheeseMaker.saltStock<(d.saltCost or 0) then return false,"Premalo soli" end; if d.spiceCost and CheeseMaker.spiceStock<(d.spiceCost or 0) then return false,"Premalo začimb" end; if d.silverCost and CheeseMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CheeseMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CheeseMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #CheeseMaker.buildings==0 then return false,"Potrebna delavnica" end; if not CheeseMaker.maker then return false,"Potreben sirar" end; return true end
function CheeseMaker.make(pt,qty) qty=qty or 5; local ok,e=CheeseMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.milkCost then CheeseMaker.milkStock=CheeseMaker.milkStock-d.milkCost*qty end; if d.rennetCost then CheeseMaker.rennetStock=CheeseMaker.rennetStock-d.rennetCost*qty end; if d.saltCost then CheeseMaker.saltStock=CheeseMaker.saltStock-d.saltCost*qty end; if d.spiceCost then CheeseMaker.spiceStock=CheeseMaker.spiceStock-d.spiceCost*qty end; if d.silverCost then CheeseMaker.silverStock=CheeseMaker.silverStock-d.silverCost*qty end; if d.goldCost then CheeseMaker.goldStock=CheeseMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CheeseMaker.jewelStock=CheeseMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if CheeseMaker.maker then t=math.max(1,t-math.floor(CheeseMaker.maker.skill/12)) end; table.insert(CheeseMaker.activeMaking,{id="cheese_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,flavorStrength=d.flavorStrength or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CheeseMaker.completeMaking(m) local q=1.0+(CheeseMaker.getQualityBonus()/100); if CheeseMaker.maker then q=q+(CheeseMaker.maker.skill/180) end; q=math.min(2.0,q); CheeseMaker.productStock[m.productType]=(CheeseMaker.productStock[m.productType] or 0)+m.quantity; CheeseMaker.totalProducts=CheeseMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CheeseMaker.maker then CheeseMaker.maker.itemsMade=CheeseMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then CheeseMaker.maker.skill=math.min(100,CheeseMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sir izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cheese.completed",{productName=m.productName,flavorStrength=m.flavorStrength,happiness=m.happiness}) end end
function CheeseMaker.update(dt) if not _G.state then return end; CheeseMaker.dayTimer=CheeseMaker.dayTimer+dt; if CheeseMaker.dayTimer>=30 then CheeseMaker.dayTimer=0; for i=#CheeseMaker.activeMaking,1,-1 do local m=CheeseMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CheeseMaker.completeMaking(m); table.remove(CheeseMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CheeseMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CheeseMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CheeseMaker.getStats() return {milkStock=CheeseMaker.milkStock,rennetStock=CheeseMaker.rennetStock,saltStock=CheeseMaker.saltStock,spiceStock=CheeseMaker.spiceStock,silverStock=CheeseMaker.silverStock,goldStock=CheeseMaker.goldStock,jewelStock=CheeseMaker.jewelStock,productStock=CheeseMaker.productStock,numBuildings=#CheeseMaker.buildings,hasMaker=CheeseMaker.maker~=nil,makerName=CheeseMaker.maker and CheeseMaker.maker.name or "—",makerSkill=CheeseMaker.maker and CheeseMaker.maker.skill or 0,activeMaking=#CheeseMaker.activeMaking,totalProducts=CheeseMaker.totalProducts} end
return CheeseMaker
